from __future__ import annotations

from datetime import date

import polars as pl
from src.backtest.strategy import MarketView, Signal, Strategy


class LowVolatilityTilting(Strategy):
    rationale = (
        "Low-volatility stocks are often considered more stable and less risky. By tilting "
        "towards these stocks, we aim to reduce overall portfolio risk while potentially "
        "maintaining returns."
    )

    def __init__(self, window: int = 20) -> None:
        self._window = window

    def generate(self, view: MarketView) -> Signal:
        stamp = _latest_visible(view)
        history = view.history(lookback=self._window)
        if history.height < self._window:
            return Signal(information_available_at=stamp, weights={})

        low_volatility_symbols = history.select(
            pl.col("symbol"),
            (pl.col("adj_close") / pl.col("adj_close").shift(1) - 1.0).alias("returns")
        ).group_by("symbol").agg(
            pl.col("returns").std().alias("volatility")
        ).sort("volatility", descending=False).select("symbol").to_series().to_list()[:5]

        if not low_volatility_symbols:
            return Signal(information_available_at=stamp, weights={})

        weight = 1.0 / len(low_volatility_symbols)
        return Signal(
            information_available_at=stamp,
            weights={s: weight for s in low_volatility_symbols}
        )


def _latest_visible(view: MarketView) -> date:
    visible = view.history()
    if visible.is_empty():
        return date(1900, 1, 1)
    newest = visible["session_date"].max()
    assert isinstance(newest, date)
    return newest
